#!/usr/bin/env python3
"""Apply the Manhastro search redirect-collapse fix to
lib/manga_manhastro/adapters/manhastro_manga_presentation_adapter.dart.

Anchored exact replacement; the anchor must match exactly once
or the script aborts without writing."""
import base64
import pathlib
import sys

TARGET = "lib/manga_manhastro/adapters/manhastro_manga_presentation_adapter.dart"

TRANSFORMS = [
    ("",
     ""),
]


def main() -> int:
    path = pathlib.Path(TARGET)
    text = path.read_text(encoding='utf-8')
    for i, (old_b64, new_b64) in enumerate(TRANSFORMS, 1):
        old = base64.b64decode(old_b64).decode('utf-8')
        new = base64.b64decode(new_b64).decode('utf-8')
        count = text.count(old)
        if count != 1:
            print(f'TRANSFORM {i}: anchor matched {count}x (need 1)')
            return 1
        text = text.replace(old, new)
        print(f'TRANSFORM {i}: ok')
    path.write_text(text, encoding='utf-8')
    print('manhastro search collapse fix applied')
    return 0


if __name__ == "__main__":
    sys.exit(main())
